/**
 * Tina Admin lands on `/#/~` after login. In our setup, the visual editor
 * preview route lives at `/tina-preview/`, so `/#/~` shows an empty shell.
 *
 * This script patches `public/admin/index.html` (generated by `tinacms build`)
 * to redirect `/#/~` → `/#/~/tina-preview/`.
 */
import fs from "node:fs";
import path from "node:path";

export function patchTinaAdminIndexHtml(
  html,
  { previewPath = "/tina-preview/" } = {}
) {
  const markerStart = "<!-- artify:tina-admin-redirect:start -->";
  const markerEnd = "<!-- artify:tina-admin-redirect:end -->";
  const script = `${markerStart}
<script>
  (function () {
    try {
      var preview = "#/~/${previewPath.replace(/^\//, "")}";
      function isTinaHome(hash) {
        return (
          hash === "#/~" ||
          hash === "#/~/" ||
          hash.startsWith("#/~?") ||
          hash.startsWith("#/~/?" )
        );
      }
      function redirectIfNeeded() {
        var h = window.location.hash || "";
        if (!isTinaHome(h)) return;
        var next = preview;
        // Preserve query params (rare, but safe).
        if (h.includes("?")) next += "?" + h.split("?").slice(1).join("?");
        // Changing only the hash may not make Tina reload the preview iframe.
        // Force a full reload once by adding a query param.
        var url = new URL(window.location.href);
        if (!url.searchParams.has("__tina_redirect")) {
          url.searchParams.set("__tina_redirect", "1");
          url.hash = next;
          window.location.replace(url.toString());
          return;
        }
        // If we've already reloaded once, just ensure the hash is correct.
        if (window.location.hash !== next) window.location.hash = next;
      }
      // 1) Immediate check on first paint
      redirectIfNeeded();
      // 2) Tina often updates the hash after auth resolves; listen for it.
      window.addEventListener("hashchange", redirectIfNeeded);
      // 3) Fallback: poll briefly in case routing happens without hashchange.
      var tries = 0;
      var max = 40; // ~10s
      var t = setInterval(function () {
        tries++;
        redirectIfNeeded();
        if (tries >= max) clearInterval(t);
      }, 250);
    } catch (e) {}
  })();
</script>
${markerEnd}`;

  // If previously patched, replace the old block with the new one.
  if (html.includes(markerStart) && html.includes(markerEnd)) {
    const start = html.indexOf(markerStart);
    const end = html.indexOf(markerEnd, start);
    if (start !== -1 && end !== -1) {
      const afterEnd = end + markerEnd.length;
      return html.slice(0, start) + script + html.slice(afterEnd);
    }
    return html;
  }

  if (html.includes("</head>")) {
    return html.replace("</head>", `${script}\n</head>`);
  }
  // Fallback: append if head tag isn't present (shouldn't happen).
  return `${html}\n${script}\n`;
}

export function patchTinaAdminIndexFile({
  rootDir = process.cwd(),
  previewPath = "/tina-preview/",
} = {}) {
  const target = path.join(rootDir, "public", "admin", "index.html");
  if (!fs.existsSync(target)) return false;

  const before = fs.readFileSync(target, "utf8");
  const after = patchTinaAdminIndexHtml(before, { previewPath });
  if (after === before) return false;
  fs.writeFileSync(target, after, "utf8");
  return true;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const changed = patchTinaAdminIndexFile();
  process.stdout.write(
    `patch-tina-admin-index: ${changed ? "patched" : "no change"}\n`
  );
}

